    res = platform.mac_ver()
    if platform.uname().system == 'Darwin':
        output = subprocess.check_output(['sw_vers'], text=True)
        for line in output.splitlines():
            if line.startswith('ProductVersion:'):
                real_ver = line.strip().split()[-1]
                break
        else:
            raise AssertionError(f'failed to parse sw_vers output: {output!r}')
        result_list = res[0].split('.')
        expect_list = real_ver.split('.')
        len_diff = len(result_list) - len(expect_list)
        if len_diff > 0:
            expect_list.extend(['0'] * len_diff)
        if result_list != ['10', '16']:
            assert result_list == expect_list, ('assertEqual', result_list, expect_list)
        assert res[1] == ('', '', ''), ('assertEqual', res[1], ('', '', ''))
        if sys.byteorder == 'little':
            assert res[2] in ('i386', 'x86_64', 'arm64'), ('assertIn', res[2], ('i386', 'x86_64', 'arm64'))
        else:
            assert res[2] == 'PowerPC', ('assertEqual', res[2], 'PowerPC')
